      offsetX: 100,
      offsetY: 100,
    });
    await expect(lineCanvas).toMatchDOMSnapshot(dir, 'step3', {
      fileFormat: 'html',
      selector: '.g2-tooltip',
    });
  });

  afterAll(() => {
    barCanvas?.destroy();
    lineCanvas?.destroy();
  });
});
